def self.jrubyify(engs)
	not_supported = [:markdown]
	engs.each_key do |key|
		engs[key].collect! { |eng| eng == :yajl ? :json_pure : eng }
		engs[key].delete_if { |eng| not_supported.include?(eng) }
	end
	engs
end

