	expect(send(verb, '/').body).to eq 'he said: hi'
	expect(send(verb, '/foo').body).to eq 'he said: ho'
end

specify 'can define nested layouts' do
	mock_app do
		layout { 'Hello <%= yield %>!' }
		template(:foo) { 'World' }
		send(verb, '/') { erb :foo }
		namespace '/foo' do
			layout { 'Hi <%= yield %>!' }
			send(verb) { erb :foo }
		end
	end

	expect(send(verb, '/').body).to eq 'Hello World!'
	expect(send(verb, '/foo').body).to eq 'Hi World!'
end

